CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE roles(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL); INSERT INTO roles(name) VALUES('customer'),('admin'),('dispatcher'),('driver') ON CONFLICT DO NOTHING;
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),full_name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE customers(user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,preferred_language TEXT NOT NULL DEFAULT 'en');
CREATE TABLE addresses(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,country TEXT NOT NULL DEFAULT 'Ethiopia',region TEXT NOT NULL,city TEXT NOT NULL,neighborhood TEXT,street_or_landmark TEXT,latitude NUMERIC(9,6),longitude NUMERIC(9,6),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE categories(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL);
CREATE TABLE products(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',category_id UUID NOT NULL REFERENCES categories(id),price_etb NUMERIC(12,2) NOT NULL CHECK(price_etb>=0),discount_percent NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK(discount_percent BETWEEN 0 AND 100),popularity INTEGER NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE product_images(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,url TEXT NOT NULL,alt_text TEXT);
CREATE TABLE inventory(product_id UUID PRIMARY KEY REFERENCES products(id) ON DELETE CASCADE,available_quantity INTEGER NOT NULL DEFAULT 0 CHECK(available_quantity>=0),reserved_quantity INTEGER NOT NULL DEFAULT 0 CHECK(reserved_quantity>=0),low_stock_threshold INTEGER NOT NULL DEFAULT 5,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE carts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID UNIQUE REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE cart_items(cart_id UUID REFERENCES carts(id) ON DELETE CASCADE,product_id UUID REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(cart_id,product_id));
CREATE TABLE orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),customer_id UUID NOT NULL REFERENCES users(id),address_id UUID NOT NULL REFERENCES addresses(id),status TEXT NOT NULL DEFAULT 'pending',delivery_type TEXT NOT NULL CHECK(delivery_type IN('local','nationwide')),subtotal_etb NUMERIC(12,2) NOT NULL,discount_etb NUMERIC(12,2) NOT NULL DEFAULT 0,delivery_fee_etb NUMERIC(12,2) NOT NULL DEFAULT 0,total_etb NUMERIC(12,2) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID REFERENCES orders(id) ON DELETE CASCADE,product_id UUID REFERENCES products(id),quantity INTEGER NOT NULL,unit_price_etb NUMERIC(12,2) NOT NULL);
CREATE TABLE payment_methods(id TEXT PRIMARY KEY,name TEXT NOT NULL); INSERT INTO payment_methods VALUES('telebirr','Telebirr'),('cbe_birr','CBE Birr'),('mpesa','M-Pesa'),('card','Visa or Mastercard'),('bank_transfer','Bank transfer'),('cod','Cash on delivery') ON CONFLICT DO NOTHING;
CREATE TABLE payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID NOT NULL REFERENCES orders(id),method TEXT NOT NULL REFERENCES payment_methods(id),status TEXT NOT NULL,amount_etb NUMERIC(12,2) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE payment_transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),payment_id UUID REFERENCES payments(id),provider_reference TEXT,provider TEXT,status TEXT,raw_payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(provider,provider_reference));
CREATE TABLE refunds(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),payment_id UUID REFERENCES payments(id),amount_etb NUMERIC(12,2) NOT NULL,status TEXT NOT NULL DEFAULT 'requested',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE delivery_providers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT UNIQUE NOT NULL,mode TEXT NOT NULL CHECK(mode IN('own_drivers','courier','manual')),active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE delivery_zones(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT UNIQUE NOT NULL,city TEXT NOT NULL,fee_etb NUMERIC(12,2) NOT NULL,active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE drivers(id UUID PRIMARY KEY REFERENCES users(id),vehicle TEXT,available BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE deliveries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID UNIQUE NOT NULL REFERENCES orders(id),provider_id UUID REFERENCES delivery_providers(id),driver_id UUID REFERENCES drivers(id),tracking_number TEXT UNIQUE,status TEXT NOT NULL DEFAULT 'pending',fee_etb NUMERIC(12,2),cash_collected_etb NUMERIC(12,2),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE delivery_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),delivery_id UUID REFERENCES deliveries(id) ON DELETE CASCADE,status TEXT NOT NULL,note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE discounts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),code TEXT UNIQUE NOT NULL,percent NUMERIC(5,2),amount_etb NUMERIC(12,2),starts_at TIMESTAMPTZ,ends_at TIMESTAMPTZ,active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE notifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id),channel TEXT NOT NULL,status TEXT NOT NULL,payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_id UUID REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id UUID,metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX products_category_idx ON products(category_id); CREATE INDEX products_name_idx ON products USING gin(to_tsvector('simple',name)); CREATE INDEX orders_customer_idx ON orders(customer_id,created_at DESC); CREATE INDEX payments_status_idx ON payments(status);
